P02-find-the-duplicate-number:
def find_duplicate(nums):
    slow = fast = 0                    # index i points to nums[i]
    while True:
        slow = nums[slow]
        fast = nums[nums[fast]]
        if slow == fast:
            break
    slow = 0                           # phase 2: meet at the cycle entry
    while slow != fast:
        slow, fast = nums[slow], nums[fast]
    return slow

P02-find-the-duplicate-number#sort:
def find_duplicate(nums):
    ordered = sorted(nums)             # a copy, so the input stays read-only
    for i in range(1, len(ordered)):
        if ordered[i] == ordered[i - 1]:
            return ordered[i]
    return -1

P02-happy-number:
def is_happy(n):
    def f(x):
        return sum(int(d) ** 2 for d in str(x))

    slow, fast = f(n), f(f(n))
    while fast != 1 and slow != fast:
        slow, fast = f(slow), f(f(fast))
    return fast == 1

P02-happy-number#set:
def is_happy(n):
    seen = set()
    while n != 1 and n not in seen:
        seen.add(n)
        n = sum(int(d) ** 2 for d in str(n))
    return n == 1

P02-linked-list-cycle:
def has_cycle(head):
    slow = fast = head
    while fast and fast.next:
        slow, fast = slow.next, fast.next.next
        if slow is fast:
            return True
    return False

P02-linked-list-cycle#set:
def has_cycle(head):
    seen = set()
    while head:
        if head in seen:
            return True
        seen.add(head)                 # nodes hash by identity
        head = head.next
    return False
